record.field:
if not records:
    raise UserError("Bitte wähle mindestens einen Sale Order aus, bevor du diese Aktion ausführst.")

for order in records:
    if order.above_text_block_ids:
        order["pre_text"] = "<br/>".join(
            text for text in order.above_text_block_ids.sorted("sequence").mapped("text") if text
        )
    if order.bottom_text_block_ids:
        order["note"] = "<br/>".join(
            text for text in order.bottom_text_block_ids.sorted("sequence").mapped("text") if text
        )
